-- Sensus multi-HPT: satu transaksi (persil) boleh berisi banyak pengamatan HPT.
-- Idempotent. Hanya menyentuh domain Sensus/RNA; tidak mengubah QC, GIS, WAD, atau IoT.
-- Salinan runtime yang sama ada di src/AuthUtility.Api/Sensus/sensus-business-output.sql (dijalankan saat startup API).
BEGIN;
SELECT pg_advisory_xact_lock(20261117, 1);

ALTER TABLE "TrnSnsHeader" ALTER COLUMN "JenisId" DROP NOT NULL;

CREATE TABLE IF NOT EXISTS "TrnSnsHptDetail" (
 "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "HeaderId" bigint NOT NULL REFERENCES "TrnSnsHeader"("Id") ON DELETE CASCADE,
 "HptId" integer NOT NULL REFERENCES "MstHpt"("Id") ON DELETE RESTRICT,
 "JumlahSerangan" integer NOT NULL,
 "Persentase" numeric(9,4),
 "HasilEvaluasi" text
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_TrnSnsHptDetail_HeaderId_HptId" ON "TrnSnsHptDetail"("HeaderId","HptId");
CREATE INDEX IF NOT EXISTS "IX_TrnSnsHptDetail_HptId" ON "TrnSnsHptDetail"("HptId");

-- Backfill observasi lama satu-HPT. Snapshot evaluasi historis tidak dikarang.
INSERT INTO "TrnSnsHptDetail" ("HeaderId","HptId","JumlahSerangan","Persentase","HasilEvaluasi")
SELECT "Id","JenisId","JumlahPokokTerserang",
 CASE WHEN "JumlahPokokSampel">0 THEN round("JumlahPokokTerserang"*100.0/"JumlahPokokSampel",4) ELSE NULL END,NULL
FROM "TrnSnsHeader" WHERE "JenisId" IS NOT NULL
ON CONFLICT ("HeaderId","HptId") DO NOTHING;

-- Header multi-HPT tidak punya JenisId; tetap tampil di view monitoring.
CREATE OR REPLACE VIEW public."VwSnsMonitoring" AS
SELECT
  h."Id", h."SensusNo", h."ClientUuid", h."JenisId",
  coalesce(j."Name", (SELECT string_agg(k."Name", ', ' ORDER BY k."Name")::varchar(150) FROM public."TrnSnsHptDetail" d JOIN public."MstHpt" k ON k."Id" = d."HptId" WHERE d."HeaderId" = h."Id")) AS "JenisName",
  h."PersilSumber", h."PersilId", h."PersilKode", h."KodeWilayah", h."KodeAfdeling", h."Komoditas",
  h."BlokId", b."Code" AS "BlokKode", b."Name" AS "BlokName",
  a."Id" AS "AfdelingId", a."Code" AS "AfdelingKode", a."Name" AS "AfdelingName",
  k."Id" AS "KebunId", k."Code" AS "KebunKode", k."Name" AS "KebunName",
  h."TanggalSensus", h."PetugasUserId", u."Name" AS "PetugasName",
  h."JumlahPokokSampel", h."JumlahPokokTerserang",
  CASE
    WHEN h."JumlahPokokSampel" > 0
      THEN round((h."JumlahPokokTerserang"::numeric * 100) / h."JumlahPokokSampel", 2)
  END AS "PersenTerserang",
  h."JenisForm", h."StatusLahan", h."StatusLahanSumber", h."FaseTanaman", h."LuasHa", h."JumlahPokokPersil",
  h."Status", h."SubmittedAt", h."ApprovedByUserId", h."ApprovedAt", h."ApprovalNote",
  h."CreatedAt", h."UpdatedAt"
FROM public."TrnSnsHeader" h
LEFT JOIN public."MstHpt" j ON j."Id" = h."JenisId"
LEFT JOIN public."MstSnsBlok" b ON b."Id" = h."BlokId"
LEFT JOIN public."MstSnsAfdeling" a ON a."Id" = b."AfdelingId"
LEFT JOIN public."MstSnsKebun" k ON k."Id" = a."KebunId"
LEFT JOIN public."UtlUser" u ON u."Id" = h."PetugasUserId";

-- Detail parameter mengikuti HPT parameter; header parcel memakai HPT dari parameternya.
CREATE OR REPLACE VIEW public."VwSnsDetailMonitoring" AS
SELECT
  d."Id", d."HeaderId", h."SensusNo", h."TanggalSensus", coalesce(h."JenisId", p."JenisId") AS "JenisId",
  j."Name" AS "JenisName",
  h."PersilSumber", h."PersilId", h."PersilKode", h."KodeWilayah", h."JenisForm", h."Status",
  d."ParameterId", p."Code" AS "ParameterCode", p."Name" AS "ParameterName", p."Satuan" AS "ParameterUnit",
  d."NoPokok", d."NilaiAngka", d."NilaiTeks"
FROM public."TrnSnsDetail" d
JOIN public."TrnSnsHeader" h ON h."Id" = d."HeaderId"
JOIN public."MstHptParameter" p ON p."Id" = d."ParameterId"
JOIN public."MstHpt" j ON j."Id" = coalesce(h."JenisId", p."JenisId");

-- Observasi per HPT untuk transaksi parcel.
CREATE OR REPLACE VIEW public."VwSnsHptMonitoring" AS
SELECT
  d."Id" AS "HptDetailId", d."HeaderId", h."SensusNo", h."TanggalSensus", h."JenisForm", h."Status",
  h."PersilSumber", h."PersilId", h."PersilKode", h."KodeWilayah", h."KodeAfdeling", h."Komoditas",
  h."JumlahPokokSampel", d."HptId", j."Code" AS "HptCode", j."Name" AS "HptName", j."ReportGroup",
  d."JumlahSerangan", d."Persentase", d."HasilEvaluasi",
  h."PetugasUserId", u."Name" AS "PetugasName", h."ApprovedByUserId", h."ApprovedAt"
FROM public."TrnSnsHptDetail" d
JOIN public."TrnSnsHeader" h ON h."Id" = d."HeaderId"
JOIN public."MstHpt" j ON j."Id" = d."HptId"
LEFT JOIN public."UtlUser" u ON u."Id" = h."PetugasUserId";

-- Satu baris per observasi HPT; header lama tanpa child tetap dihitung sekali.
CREATE OR REPLACE VIEW public."VwRnaRingkasan" AS
WITH obs AS (
  SELECT h."TanggalSensus", h."JenisId", h."JumlahPokokSampel", h."JumlahPokokTerserang", h."Status", h."KodeWilayah"
  FROM public."TrnSnsHeader" h
  WHERE h."JenisId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public."TrnSnsHptDetail" d WHERE d."HeaderId" = h."Id")
  UNION ALL
  SELECT h."TanggalSensus", d."HptId", h."JumlahPokokSampel", d."JumlahSerangan", h."Status", h."KodeWilayah"
  FROM public."TrnSnsHeader" h
  JOIN public."TrnSnsHptDetail" d ON d."HeaderId" = h."Id"
)
SELECT
  date_trunc('month', o."TanggalSensus")::date AS "Periode",
  o."JenisId", j."Name" AS "JenisName", o."KodeWilayah",
  count(*) AS "TotalSensus",
  count(*) FILTER (WHERE o."Status" = 'SUBMITTED') AS "Submitted",
  count(*) FILTER (WHERE o."Status" = 'APPROVED') AS "Approved",
  count(*) FILTER (WHERE o."Status" = 'REVISI') AS "Revisi",
  count(*) FILTER (WHERE o."Status" = 'REJECTED') AS "Rejected",
  coalesce(sum(o."JumlahPokokSampel"), 0) AS "TotalPokokSampel",
  coalesce(sum(o."JumlahPokokTerserang"), 0) AS "TotalPokokTerserang"
FROM obs o
JOIN public."MstHpt" j ON j."Id" = o."JenisId"
GROUP BY 1, 2, 3, 4;

COMMIT;
